package dev.cosmerearcanists.power;
import dev.cosmerearcanists.*;
import dev.cosmerearcanists.mobs.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.npc.Villager;
import net.minecraft.world.level.ChunkPos;
import net.neoforged.neoforge.gametest.*;
@GameTestHolder(CosmereArcanists.MOD_ID)
@PrefixGameTestTemplate(false)
public final class PowerChunkGameTests {
    private static long count(Villager mob){return PowerAttributes.keys().stream().filter(k->mob.getAttribute(PowerAttributes.holder(k)).getBaseValue()>0).count();}
    private static ChunkPos unused(GameTestHelper h){var book=NaturalPowerChunks.get(h.getLevel().getServer());long now=h.getLevel().getServer().overworld().getGameTime();var base=new ChunkPos(h.absolutePos(net.minecraft.core.BlockPos.ZERO));for(int i=100;i<1000;i++){var pos=new ChunkPos(base.x+i,base.z+100);if(book.available(new ChunkPowerLedger.Key(h.getLevel().dimension().location().toString(),pos.toLong()),now))return pos;}throw new IllegalStateException("No unused fixture chunk");}
    private static Villager mob(GameTestHelper h,ChunkPos chunk){var mob=EntityType.VILLAGER.create(h.getLevel());mob.setPos(chunk.getMinBlockX()+8.5,50,chunk.getMinBlockZ()+8.5);return mob;}
    @GameTest(template="empty") public static void cooldownPersistsAndExpiresAtOneHourPerDimensionChunk(GameTestHelper h){var data=new NaturalPowerChunks();var key=new ChunkPowerLedger.Key("minecraft:overworld",ChunkPos.asLong(-2,3));long now=100;h.assertTrue(data.claim(key,now,72000),"First success reserves the birth chunk");var tag=data.save(new CompoundTag(),h.getLevel().registryAccess());var loaded=NaturalPowerChunks.load(tag,h.getLevel().registryAccess());h.assertTrue(!loaded.available(key,now+71999),"Saved cooldown still blocks one tick before an hour");h.assertTrue(loaded.available(new ChunkPowerLedger.Key("cosmerearcanists:scadrial",key.chunk()),now)&&loaded.available(new ChunkPowerLedger.Key(key.dimension(),ChunkPos.asLong(-1,3)),now),"Other dimensions and adjacent chunks remain independent");h.assertTrue(loaded.available(key,now+72000)&&loaded.claim(key,now+72000,72000),"Eligible again exactly at the one-hour boundary");h.succeed();}
    @GameTest(template="empty") public static void successfulMobBirthLocksChunkEvenIfDonorDiesOrMoves(GameTestHelper h){int oldOdds=NaturalMobConfig.ONE_IN.get(),oldSeconds=NaturalMobConfig.CHUNK_COOLDOWN_SECONDS.get();try{NaturalMobConfig.ONE_IN.set(1);NaturalMobConfig.CHUNK_COOLDOWN_SECONDS.set(3600);var chunk=unused(h);var first=mob(h,chunk);NaturalMobPowers.initialize(first);h.assertTrue(count(first)>0,"Forced successful roll grants powers");first.setHealth(0);var blocked=mob(h,chunk);NaturalMobPowers.initialize(blocked);h.assertTrue(count(blocked)==0&&NaturalMobPowers.checked(blocked),"Next birth is ordinary despite100percent chance and donor death");var other=unused(h);blocked.setPos(other.getMinBlockX()+8.5,50,other.getMinBlockZ()+8.5);NaturalMobPowers.initialize(blocked);h.assertTrue(count(blocked)==0,"Moving a blocked mob cannot reroll its birth");var fresh=mob(h,other);NaturalMobPowers.initialize(fresh);h.assertTrue(count(fresh)>0,"A fresh mob in another chunk can still receive powers");}finally{NaturalMobConfig.ONE_IN.set(oldOdds);NaturalMobConfig.CHUNK_COOLDOWN_SECONDS.set(oldSeconds);}h.succeed();}
    @GameTest(template="empty") public static void unsuccessfulRollDoesNotConsumeChunkAllowance(GameTestHelper h){int oldOdds=NaturalMobConfig.ONE_IN.get(),oldSeconds=NaturalMobConfig.CHUNK_COOLDOWN_SECONDS.get();try{NaturalMobConfig.ONE_IN.set(1000000);NaturalMobConfig.CHUNK_COOLDOWN_SECONDS.set(3600);var chunk=unused(h);var failed=mob(h,chunk);failed.getRandom().setSeed(0);NaturalMobPowers.initialize(failed);h.assertTrue(count(failed)==0,"Deterministic unsuccessful roll leaves an ordinary mob");NaturalMobConfig.ONE_IN.set(1);var success=mob(h,chunk);NaturalMobPowers.initialize(success);h.assertTrue(count(success)>0,"Failure did not lock the chunk");}finally{NaturalMobConfig.ONE_IN.set(oldOdds);NaturalMobConfig.CHUNK_COOLDOWN_SECONDS.set(oldSeconds);}h.succeed();}
}
